package dev.joaomendonca.agendapro.finance.api;import dev.joaomendonca.agendapro.finance.application.FinanceService;import jakarta.validation.Valid;import org.springframework.format.annotation.DateTimeFormat;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;import java.util.*;
@RestController @RequestMapping("/api/v1/finance") public class FinanceController{private final FinanceService service;public FinanceController(FinanceService s){service=s;}@GetMapping("/transactions") public List<FinancialTransactionResponse> list(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.list(from,to);}@PostMapping("/transactions") @ResponseStatus(HttpStatus.CREATED) public FinancialTransactionResponse create(@Valid @RequestBody FinancialTransactionRequest r){return service.create(r);}@PutMapping("/transactions/{id}") public FinancialTransactionResponse update(@PathVariable UUID id,@Valid @RequestBody FinancialTransactionRequest r){return service.update(id,r);}@DeleteMapping("/transactions/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);}@GetMapping("/summary") public FinanceSummaryResponse summary(@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate from,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate to){return service.summary(from,to);}}
